    @Transactional
    public List<Person> bulkRetire(String sheetId, String user, List<Long> ids, LocalDate date) {
        try {
            roles.refuseViewer(sheetId, user);
        } catch (ResponseStatusException e) {
            if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
                return List.of();
            }
            throw e;
